-- A person's aliases, stored trimmed. An alias shares the names' uniqueness on the sheet (compared
-- without regard to case, by the lower-cased key): no alias equals any name or other alias there.
CREATE TABLE person_alias (
    person_id BIGINT NOT NULL REFERENCES person (id),
    alias VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(alias)),
    CONSTRAINT person_alias_once UNIQUE (person_id, alias_key)
);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored with
-- surrounding spaces removed, so the comparison key is just the lower-cased name.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
